use crate::aap::caps::inference_llm;

struct Node;

/// Map a free-text label from the model onto the closed `Intent` enum.
///
/// The enum has no "other" case, so adversarial text cannot widen the intent
/// set: anything we don't recognise collapses to `Unknown`. This is the
/// `ensures intent in [...]` property, discharged by the type plus this fallback.
fn classify_intent(label: &str) -> Intent {
    let l = label.trim().to_ascii_lowercase();
    if l.contains("billing") {
        Intent::BillingQuestion
    } else if l.contains("technical") || l.contains("support") {
        Intent::TechnicalSupport
    } else if l.contains("account") {
        Intent::AccountChange
    } else if l.contains("general") {
        Intent::GeneralInquiry
    } else {
        Intent::Unknown
    }
}

/// Truncate `s` to at most `max` bytes without splitting a UTF-8 code point.
fn bounded(s: &str, max: usize) -> String {
    if s.len() <= max {
        return s.to_string();
    }
    let mut end = max;
    while end > 0 && !s.is_char_boundary(end) {
        end -= 1;
    }
    s[..end].to_string()
}

impl Guest for Node {
    fn run(message: RawMessage) -> CustomerQuery {
        // `requires len(value.text) <= 4000` holds of every input; we don't
        // re-check it, but we never rely on it being larger either.
        let text = message.text;

        // One inference call. `inference-llm` is the node's entire authority:
        // it can be influenced by the model's answer but cannot act on it
        // (no tool interface exists to invoke).
        let intent_label = inference_llm::infer(
            "You are an intent classifier for a customer support system. \
             Reply with exactly one of these labels and nothing else: \
             billing_question, technical_support, account_change, \
             general_inquiry, unknown.",
            &text,
            "classify",
        );

        let intent = classify_intent(&intent_label);

        // `ensures len(question) <= 512` — enforced here regardless of input.
        let question = bounded(&text, 512);

        CustomerQuery {
            intent,
            entities: Vec::new(),
            question,
        }
    }
}

export!(Node);
